  let score: Int = 87;

  io.println("Your score:");
  io.println("87");

  if score >= 90 {
    io.println("Grade: A � Outstanding!");
  } elif score >= 80 {
    io.println("Grade: B � Great work!");
  } elif score >= 70 {
    io.println("Grade: C � Good effort.");
  } elif score >= 60 {
    io.println("Grade: D � You passed.");
  } else {
    io.println("Grade: F � Keep studying, you'll get it!");
  }

  let score2: Int = 45;
  io.println("Another score:");
  io.println("45");

  if score2 >= 90 {
    io.println("Grade: A");
  } elif score2 >= 80 {
    io.println("Grade: B");
  } elif score2 >= 70 {
    io.println("Grade: C");
  } elif score2 >= 60 {
    io.println("Grade: D");
  } else {
    io.println("Grade: F");
  }
}
